import * as THREE from 'three';
import {createToyKit,disposeToyTree} from '../world/toy-kit.js';
import {recipeById,evaluateCooking} from './cooking-model.js';
/** Owned tools in the real kitchen; the original Dormi and room are borrowed. */
export function createCookingSession({scene,zoneRoot,player,model,poser,visual,reduced=false}){
 const saved={parent:player.parent,position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),pose:poser.getState(),children:player.children.map(o=>[o,o.visible]),old:[]};
 const root=new THREE.Group();root.name='homeKitchen.recipe-lab';zoneRoot.add(root);const k=createToyKit(root),{box,sphere,cylinder}=k;
 const camera=new THREE.OrthographicCamera(-2.6,2.6,1.95,-1.95,.05,100);root.add(camera);camera.position.set(3.5,3.8,-3.1);root.updateWorldMatrix(true,true);camera.lookAt(root.localToWorld(new THREE.Vector3(0,1.25,-1.9)));
 const step=box(1.55,.42,1.10,'#9db4a0',0,.21,-1.02,.08);step.name='cooking.step';box(1.57,.06,1.12,'#d4ddbb',0,.45,-1.02,.04);
 const board=box(3.0,.05,.95,'#d2b38b',0,1.185,-2.04,.07);board.name='cooking.workboard';
 const bowl=new THREE.Group();bowl.name='cooking.bowl';bowl.position.set(-.44,1.23,-1.99);root.add(bowl);const bm=k.mat('#85adb0');bm.side=THREE.DoubleSide;const rim=new THREE.Mesh(new THREE.CylinderGeometry(.40,.29,.22,28,1,true),bm);rim.position.y=.11;bowl.add(rim);cylinder(.29,.29,.025,'#85adb0',0,0,0,bowl);const lip=new THREE.Mesh(new THREE.TorusGeometry(.40,.019,7,28),bm);lip.rotation.x=Math.PI/2;lip.position.y=.22;bowl.add(lip);
 const filling=cylinder(.365,.285,.045,'#e7dab5',0,.055,0,bowl),pieces=[];for(let i=0;i<12;i++){const m=sphere(.085,'#b3ba79',Math.cos(i*2.4)*(.08+i%3*.075),.16,Math.sin(i*2.4)*(.08+i%3*.075),1,.75,1,bowl);m.material=m.material.clone();m.name='cooking.mix-piece.'+i;pieces.push(m);}
 const cup=new THREE.Group();cup.name='cooking.measuring-cup';root.add(cup);cylinder(.12,.10,.22,'#fff0ce',0,0,0,cup);const handle=new THREE.Mesh(new THREE.TorusGeometry(.074,.015,6,14),k.mat('#bf9e76'));handle.position.x=.135;cup.add(handle);for(let j=0;j<3;j++)box(.052,.012,.01,'#8b9d94',0,-.065+j*.05,.119,.002,cup);
 const stream=cylinder(.025,.03,.25,'#f4e0b5',0,0,0);stream.name='cooking.pour-stream';
 const spoon=new THREE.Group();spoon.name='cooking.spoon';root.add(spoon);const rod=cylinder(.018,.018,.42,'#aa855d',0,-.14,0,spoon);sphere(.068,'#aa855d',0,-.37,0,1,.25,1.3,spoon);
 const pan=new THREE.Group();pan.name='cooking.pan';pan.position.set(.73,1.23,-2.02);root.add(pan);cylinder(.40,.37,.09,'#626e70',0,.04,0,pan);box(.13,.09,.48,'#a38465',.08,.065,.40,.03,pan);const food=cylinder(.31,.29,.085,'#e6c790',0,.115,0,pan);food.name='cooking.finished-food';
 const heatRing=new THREE.Mesh(new THREE.TorusGeometry(.38,.018,6,28),k.mat('#e5a24c'));heatRing.rotation.x=Math.PI/2;heatRing.position.y=.01;pan.add(heatRing);
 const mug=new THREE.Group();mug.name='cooking.cocoa-mug';mug.position.copy(pan.position);root.add(mug);const mugMat=k.mat('#b7ccc3');mugMat.side=THREE.DoubleSide;const mugWall=new THREE.Mesh(new THREE.CylinderGeometry(.245,.22,.34,24,1,true),mugMat);mugWall.position.y=.17;mug.add(mugWall);const cocoa=cylinder(.228,.228,.025,'#b58963',0,.30,0,mug);const mh=new THREE.Mesh(new THREE.TorusGeometry(.12,.034,8,18),mugMat);mh.position.set(.28,.18,0);mug.add(mh);
 const steam=[];for(let i=0;i<4;i++)steam.push(sphere(.04,'#e7e7d4',.73+(i-1.5)*.1,1.65+i*.08,-2.02,.5,2,1));
 const jars=[];for(let i=0;i<3;i++){const g=new THREE.Group();g.name='cooking.ingredient.'+i;g.position.set(-1.10+i*.48,1.24,-2.53);root.add(g);cylinder(.16,.16,.26,'#eee2c5',0,.13,0,g);const fill=cylinder(.144,.144,.025,'#eee2c5',0,.26,0,g);fill.material=fill.material.clone();jars.push(fill);box(.065,.09,.011,'#8ca59b',0,.15,.163,.01,g);}
 for(const mesh of Object.values(visual?.kitchen??{}).flat()){if(mesh?.isObject3D){saved.old.push([mesh,mesh.visible]);mesh.visible=false;}}
 zoneRoot.add(player);player.position.set(0,.49,-1.02);player.rotation.set(0,Math.PI,0);player.scale.set(1,1,1);model.position.set(0,0,0);model.quaternion.identity();model.scale.set(1,1,1);for(const [child]of saved.children)if(child!==model)child.visible=false;
 let alive=true,state,lastPour=0,pourTime=0,flipTime=0,clock=0;
 function anchors(){root.updateWorldMatrix(true,true);player.updateWorldMatrix(true,true);return Object.fromEntries(['leftHand','rightHand'].map(id=>[id,root.worldToLocal(player.localToWorld(new THREE.Vector3(...poser.getState().anchors[id])))]));}
 function draw(){if(!alive||!state)return;const recipe=recipeById(state.recipe),result=evaluateCooking(state),pouring=pourTime>0&&state.phase==='measure';poser.setPose(pouring?'cookPour':state.phase==='mix'?'cookMix':state.phase==='heat'?'cookPan':'cookReady',1,reduced?0:state.phase==='mix'?state.turns*1.7:clock);const a=anchors();cup.position.copy(a.rightHand).add(new THREE.Vector3(0,.055,-.02));cup.rotation.z=pouring?-.9:0;cup.visible=state.phase==='measure';stream.visible=pouring&&!reduced;stream.position.copy(cup.position).add(new THREE.Vector3(-.09,-.19,0));stream.material.color.set(recipe.colors[lastPour]);spoon.visible=state.phase==='mix';spoon.position.copy(a.rightHand);spoon.quaternion.setFromUnitVectors(new THREE.Vector3(0,-1,0),new THREE.Vector3(-.44,1.35,-1.99).sub(a.rightHand).normalize());
  const total=state.order.length;filling.visible=total>0;filling.scale.y=Math.max(.3,total/5);filling.position.y=.05+total*.006;filling.material.color.set(state.phase==='result'?result.color:recipe.colors[1]);for(let i=0;i<3;i++)jars[i].material.color.set(recipe.colors[i]);for(let i=0;i<12;i++){pieces[i].visible=i<total&&(state.recipe==='salad'||state.turns<3);pieces[i].material.color.set(recipe.colors[state.order[i]??0]);pieces[i].scale.setScalar(state.turns>recipe.mix[1]?.6:1);pieces[i].position.y=.16+Math.sin(i)*.012;}
  mug.visible=state.recipe==='cocoa'&&state.phase==='result';cocoa.material.color.set(result.color);pan.visible=state.recipe!=='salad'&&!mug.visible;pan.rotation.z=reduced?0:Math.sin(flipTime/.65*Math.PI)*.12;food.position.y=.115+(reduced?0:Math.sin(flipTime/.65*Math.PI)*.18);food.visible=['heat','result'].includes(state.phase);food.material.color.set(result.color);food.scale.set(1,state.recipe==='cocoa'?.2:result.texture==='dense'?.7:1.3,1);heatRing.visible=state.phase==='heat'&&state.running;for(let i=0;i<steam.length;i++){steam[i].visible=state.phase==='heat'&&state.energy>8;steam[i].position.y=1.55+(reduced?i*.1:((clock*.3+i*.18)%.7));}root.updateWorldMatrix(true,true);
 }
 return {root,camera,scene,update(next){if(!alive)return;if(state&&next.order.length>state.order.length){lastPour=next.order.at(-1);pourTime=.7;}else if(!state&&next.order.length){lastPour=next.order.at(-1);pourTime=.7;}if(state&&next.flipEnergy!==state.flipEnergy&&next.flipEnergy!==null)flipTime=.65;state=next;draw();},tick(dt){if(!alive||!state)return;clock+=Math.min(.1,Math.max(0,dt));pourTime=Math.max(0,pourTime-dt);flipTime=Math.max(0,flipTime-dt);draw();},dispose(){if(!alive)return;alive=false;saved.parent.add(player);player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);for(const[o,v]of [...saved.children,...saved.old])o.visible=v;disposeToyTree(root);root.removeFromParent();}};
}
export function createCookingViewport({canvas,session,onFailure=()=>{}}){let renderer,alive=true,lastW=0,lastH=0;try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio??1,1.4));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;}catch{onFailure();}
 const lost=e=>{e.preventDefault();onFailure();};canvas.addEventListener('webglcontextlost',lost);
 return {render(){if(!alive||!renderer)return;const r=canvas.getBoundingClientRect(),w=Math.max(1,Math.min(900,Math.round(r.width))),h=Math.max(1,Math.min(520,Math.round(r.height)));if(w!==lastW||h!==lastH){lastW=w;lastH=h;renderer.setSize(w,h,false);const aspect=w/h,span=Math.max(3.6,5/aspect);Object.assign(session.camera,{left:-span*aspect/2,right:span*aspect/2,top:span/2,bottom:-span/2});session.camera.updateProjectionMatrix();}renderer.render(session.scene,session.camera);},dispose(){if(!alive)return;alive=false;canvas.removeEventListener('webglcontextlost',lost);renderer?.renderLists.dispose();renderer?.dispose();renderer?.forceContextLoss();}};
}
